<div class="card" style="padding:0"><table><thead><tr><th><?= e(__('Codice')) ?></th><th><?= e(__('Sconto')) ?></th><th><?= e(__('Utilizzi')) ?></th><th><?= e(__('Scadenza')) ?></th><th><?= e(__('Stato')) ?></th></tr></thead><tbody>
<?php foreach ($rows as $c): ?><tr><td><a href="<?= e(url('admin/coupons/' . $c['id'])) ?>"><strong><?= e($c['code']) ?></strong></a></td><td><?= $c['type'] === 'percent' ? (int)$c['value'] . '%' : e(money($c['value'])) ?><?= $c['free_shipping'] ? ' + ' . e(__('spedizione gratuita')) : '' ?></td><td><?= (int)$c['used'] ?><?= $c['max_uses'] ? ' / ' . (int)$c['max_uses'] : '' ?></td><td><?= e($c['expires_at'] ? date('d/m/Y', strtotime($c['expires_at'])) : '—') ?></td><td><?= a_status($c['active'] ? 'active' : 'draft') ?></td></tr><?php endforeach ?>
<?php if (!$rows): ?><tr><td colspan="5" class="muted"><?= e(__('Nessun codice sconto.')) ?></td></tr><?php endif ?></tbody></table></div>
